"""Conversation queue for event-based channel communication."""

from __future__ import annotations

import asyncio
import itertools
from dataclasses import dataclass, field
from typing import (
    Any,
    Callable,
    Generic,
    Optional,
    Protocol,
    TypeVar,
    runtime_checkable,
)

import structlog

structlogger = structlog.get_logger()

T = TypeVar("T")


@dataclass(order=True, frozen=True)
class _QueueItem(Generic[T]):
    """Envelope stored on the backing queue.

    `priority` and `sequence` order the item on a priority queue (`sequence`
    breaks ties, keeping equal priorities FIFO); `event` is never compared. Both
    are `None` on a FIFO queue.
    """

    priority: Any
    sequence: Optional[int]
    event: T = field(compare=False)


@runtime_checkable
class ConversationQueue(Protocol[T]):
    """Typed async event queue for conversation events.

    Default implementation wraps asyncio.Queue. This protocol allows for
    distributed backends (Redis Streams, Kafka) to be swapped in without
    changing call sites.

    The protocol is generic over event type T to allow different channels to use
    different event hierarchies (e.g., voice events vs text events), though in
    practice most will use InputEvent or its subclasses.
    """

    @property
    def conversation_id(self) -> str:
        """The conversation ID this queue belongs to."""
        ...

    @property
    def input_channel(self) -> str:
        """The input channel name that produced events for this queue."""
        ...

    @property
    def is_priority_queue(self) -> bool:
        """Whether events are dequeued by priority (rather than FIFO)."""
        ...

    async def put(self, event: T) -> None:
        """Add an event to the queue.

        Args:
            event: The event to enqueue.
        """
        ...

    async def get(self) -> T:
        """Get the next event from the queue.

        Blocks until an event is available.

        Returns:
            The next event in the queue.
        """
        ...

    async def drain(self) -> list[T]:
        """Drain all available events from the queue.

        Returns all events currently in the queue without blocking.
        If the queue is empty, returns an empty list.

        This is used to prevent the bot from responding to stale input
        by processing all pending events in a single batch.

        Returns:
            List of all events currently in the queue.
        """
        ...

    async def drain_while(self, predicate: Callable[[T], bool]) -> list[T]:
        """Drain events from the front of the queue while *predicate* holds.

        Never blocks. The first event that fails *predicate* stays at the front
        and is returned by the next ``get`` or ``drain``.

        Args:
            predicate: Decides whether the next event is taken.

        Returns:
            The taken events, in queue order.
        """
        ...

    async def get_batch(self) -> list[T]:
        """Block until the first event, then drain the rest without blocking.

        Waits on `get()` for the first item (so the caller does not busy-spin on an
        empty queue), then `drain()` for any further items already queued. The returned
        list is never empty when this coroutine completes.

        Returns:
            Non-empty list `[first, *rest]` for this batch.
        """
        ...


class InMemoryConversationQueue(Generic[T]):
    """In-memory implementation of ConversationQueue using asyncio.Queue.

    This is the default implementation for voice conversations. For most use cases,
    an in-memory queue is sufficient and distributed backends are not needed.

    Args:
        conversation_id: The conversation ID this queue belongs to.
        input_channel: The input channel name that produced events for this queue.
        maxsize: Maximum number of events the queue can hold. If maxsize is 0,
            the queue size is unlimited.
        priority_key: Optional callable returning a comparable priority for an
            event (lower dequeues first). When given, the queue dequeues by
            priority instead of FIFO; equal priorities keep insertion order.
    """

    def __init__(
        self,
        conversation_id: str,
        input_channel: str,
        maxsize: int = 50,
        *,
        priority_key: Optional[Callable[[T], Any]] = None,
    ) -> None:
        """Initialize the queue.

        Args:
            conversation_id: The conversation ID this queue belongs to.
            input_channel: The input channel name that produced events for this queue.
            maxsize: Maximum number of events the queue can hold. Defaults to 50.
            priority_key: Optional priority extractor; when set the queue is
                priority-ordered (lower value first) instead of FIFO.
        """
        self._conversation_id = conversation_id
        self._input_channel = input_channel
        self._priority_key = priority_key
        # Front event left in place by ``drain_while``; served before the queue.
        self._held: Optional[_QueueItem[T]] = None

        if priority_key is None:
            self._queue: asyncio.Queue[_QueueItem[T]] = asyncio.Queue(maxsize=maxsize)
        else:
            # Events are wrapped in _QueueItem(priority, sequence, event); the
            # monotonic sequence breaks ties so equal-priority events stay FIFO
            # and the events themselves are never compared.
            self._queue = asyncio.PriorityQueue(maxsize=maxsize)
            self._sequence = itertools.count()

        structlogger.debug(
            "conversation_queue.created",
            conversation_id=conversation_id,
            input_channel=input_channel,
            maxsize=maxsize,
        )

    @property
    def conversation_id(self) -> str:
        """The conversation ID this queue belongs to."""
        return self._conversation_id

    @property
    def input_channel(self) -> str:
        """The input channel name that produced events for this queue."""
        return self._input_channel

    @property
    def is_priority_queue(self) -> bool:
        """Whether events are dequeued by priority (rather than FIFO)."""
        return self._priority_key is not None

    @property
    def size(self) -> int:
        """Return the number of events currently queued."""
        return self._queue.qsize() + (self._held is not None)

    async def put(self, event: T) -> None:
        """Add an event to the queue.

        Blocks if the queue is full (when maxsize > 0).

        Args:
            event: The event to enqueue.
        """
        queue_event = self._wrap(event)
        await self._queue.put(queue_event)

    async def get(self) -> T:
        """Get the next event from the queue.

        Blocks until an event is available.

        Returns:
            The next event in the queue.
        """
        if self._held is not None:
            item, self._held = self._held, None
            return self._unwrap(item)
        event = self._unwrap(await self._queue.get())
        return event

    async def drain(self) -> list[T]:
        """Drain all available events from the queue.

        Returns all events currently in the queue without blocking.
        If the queue is empty, returns an empty list.

        This prevents the bot from responding to stale input by processing
        all pending events in a single batch.

        Returns:
            List of all events currently in the queue.
        """
        events: list[T] = []
        if self._held is not None:
            events.append(self._unwrap(self._held))
            self._held = None

        # Get all events from the queue without blocking.
        while not self._queue.empty():
            try:
                item = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                # Race condition: queue became empty between check and get
                break
            event = self._unwrap(item)
            events.append(event)

        if events:
            structlogger.debug(
                "conversation_queue.drained",
                conversation_id=self._conversation_id,
                event_count=len(events),
                event_types=[type(e).__name__ for e in events],
            )

        return events

    async def drain_while(self, predicate: Callable[[T], bool]) -> list[T]:
        """Drain events from the front of the queue while *predicate* holds.

        Never blocks. The first event that fails *predicate* stays at the front
        and is returned by the next ``get`` or ``drain``. On a priority queue that
        event is served next even if a higher-priority event arrives later.

        Args:
            predicate: Decides whether the next event is taken.

        Returns:
            The taken events, in queue order.
        """
        events: list[T] = []
        while True:
            if self._held is not None:
                item, self._held = self._held, None
            else:
                try:
                    item = self._queue.get_nowait()
                except asyncio.QueueEmpty:
                    return events
            if not predicate(self._unwrap(item)):
                self._held = item
                return events
            events.append(self._unwrap(item))

    async def get_batch(self) -> list[T]:
        """Block until the first event, then drain the rest without blocking.

        Waits on `get()` for the first item (so the caller does not busy-spin on an
        empty queue), then `drain()` for any further items already queued. The returned
        list is never empty when this coroutine completes.

        Returns:
            Non-empty list `[first, *rest]` for this batch.
        """
        first = await self.get()
        rest = await self.drain()
        batch = [first, *rest]
        return batch

    def _wrap(self, event: T) -> _QueueItem[T]:
        """Encode an event into a `_QueueItem` for the backing queue.

        FIFO queues carry `priority=None`, `sequence=None`; priority queues carry
        the extracted priority and a monotonic `sequence` tie-break.
        """
        if self._priority_key is None:
            return _QueueItem(priority=None, sequence=None, event=event)
        return _QueueItem(
            priority=self._priority_key(event),
            sequence=next(self._sequence),
            event=event,
        )

    def _unwrap(self, item: _QueueItem[T]) -> T:
        """Recover the event stored by ``_wrap``."""
        return item.event

    def _priority_of(self, event: T) -> Any:
        """The event's priority for logging (``None`` on a FIFO queue)."""
        return None if self._priority_key is None else self._priority_key(event)
